"""Clinical math formulas for vitals-calc.

All public functions raise ValueError with a one-line message when the
inputs are physiologically invalid.
"""


def bmi(weight_kg: float, height_cm: float) -> float:
    """Body Mass Index = weight(kg) / height(m)^2."""
    _require_positive(weight_kg=weight_kg, height_cm=height_cm)
    return round(weight_kg / (height_cm / 100.0) ** 2, 2)


def bsa(weight_kg: float, height_cm: float, method: str) -> float:
    """Body Surface Area (m^2). Methods: mosteller, du_bois, haycock."""
    _require_positive(weight_kg=weight_kg, height_cm=height_cm)
    h = height_cm / 100.0
    if method == "mosteller":
        value = (height_cm * weight_kg / 3600.0) ** 0.5
    elif method == "du_bois":
        # Du Bois & Du Bois (1916): 0.007184 * H^0.725 * W^0.425
        value = 0.007184 * (height_cm**0.725) * (weight_kg**0.425)
    elif method == "haycock":
        # Haycock et al. (1978): 0.024265 * H^0.3964 * W^0.5378
        value = 0.024265 * (height_cm**0.3964) * (weight_kg**0.5378)
    else:
        raise ValueError(f"unknown BSA method: {method!r}")
    return round(value, 2)


def map_(sbp: float, dbp: float) -> float:
    """Mean Arterial Pressure = DBP + (SBP - DBP)/3."""
    _require_positive(sbp=sbp, dbp=dbp)
    if dbp >= sbp:
        raise ValueError("invalid physiology: diastolic pressure must be below systolic")
    return round(dbp + (sbp - dbp) / 3.0, 1)


def _require_positive(**values: float) -> None:
    for name, val in values.items():
        if val <= 0:
            raise ValueError(f"invalid input: {name} must be positive")

